// Entrada: JSON con { producto, email } desde checkout.js
// PayPal envía el pago y, al confirmarse, este nodo recibe el pedido
// pendiente. Aquí solo normalizamos campos.
const datos = {
  email: $json.email || '',
  producto: typeof $json.producto === 'string' ? $json.producto.trim() : '',
  enlacePaypal: $json.enlacePaypal || '',
  pagoId: ($json.id || $json.paymentId || $json.resource_id || '').toString()
};
return [datos];

// Verifica en PayPal que el pago esté COMPLETADO (COMPLETED)
// y que el importe coincida. Reemplaza el client_id / secret en el
// nodo de credenciales "PayPal API" (Credenciales > Nueva > PayPal API).
// La llamada ya estructura el verify a /v2/checkout/orders/{id}.
const opciones = {
  method: 'GET',
  url: 'https://api-m.paypal.com/v2/checkout/orders/' +
    encodeURIComponent($json.pagoId),
  auth: {
    // Usa la credencial 'PayPal API' con tu client_id y client_secret
    // (PayPal Developer > Apps > Tu app > Live API credentials)
    type: 'paypalApi'
  },
  json: true
};
return await this.helpers.httpRequest(opciones).then(res => {
  const estado = res.status || '';
  const ok = estado === 'COMPLETED' || estado === 'APPROVED';
  return [{ ...$json, _paypal_valido: ok, _paypal_estado: estado }];
});

// Busca la clave correspondiente en tu hoja 'claves'.
// Formato esperado de la hoja:  producto | clave | vendido(SÍ/NO)
// Reemplaza la lógica por tu API/script si usas otro método.
const filas = $json.result || [];
return filas.filter(f => String(f.producto).toLowerCase() === String($json.producto).toLowerCase());

